package com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.verify;import com.bct.ngtpa.apiservice.application.dto.auth.login.account.LoginSessionAccount;import java.util.*;public record VerifyLoginOtpResult(VerifyLoginOtpStatus status,Integer remainingVerifyAttempts,boolean clearAuthFlowCookie,List<LoginSessionAccount> accounts){public VerifyLoginOtpResult{Objects.requireNonNull(status);accounts=accounts==null?List.of():List.copyOf(accounts);if(status==VerifyLoginOtpStatus.ACCOUNTS_READY&&accounts.isEmpty())throw new IllegalArgumentException("ACCOUNTS_READY requires accounts");if(status!=VerifyLoginOtpStatus.ACCOUNTS_READY&&!accounts.isEmpty())throw new IllegalArgumentException("Failure result cannot carry accounts");}public VerifyLoginOtpResult(VerifyLoginOtpStatus status,Integer remainingVerifyAttempts,boolean clearAuthFlowCookie){this(status,remainingVerifyAttempts,clearAuthFlowCookie,List.of());}@Override public String toString(){return "VerifyLoginOtpResult[status="+status+", remainingVerifyAttempts="+remainingVerifyAttempts+", clearAuthFlowCookie="+clearAuthFlowCookie+", accountCount="+accounts.size()+"]";}}
